// Gemini API key rotation.
//
// Reads from n8n VARIABLES first, then environment variables.
//
// That order matters: this instance is n8n Cloud, where environment variables
// cannot be set by the user at all. The original version read only $env, so on
// Cloud it would always throw "No Gemini keys found" no matter how many keys
// existed. $vars is the Cloud-native store; $env is kept as the fallback so the
// same workflow still runs unchanged on a self-hosted instance later.
//
// Keys are NEVER written into a node parameter. A key pasted into a parameter
// travels inside every export of this workflow, and a Google API key that
// reaches a repository is scraped and abused within minutes.
//
// The index advances on every call and is carried in workflow static data, so
// it survives between runs. A 429 or 5xx on the HTTP node retries, and because
// this node re-runs, the retry lands on the NEXT key rather than hammering the
// exhausted one.
const read = (name) => {
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return $vars[name];
  } catch (e) { /* $vars not available on this instance */ }
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return $env[name];
  } catch (e) { /* $env blocked, which is the normal case on Cloud */ }
  return null;
};

const keys = [];
for (let i = 1; i <= 7; i++) {
  const k = read(`GEMINI_API_KEY_${i}`);
  if (k) keys.push(String(k).trim());
}

if (keys.length === 0) {
  throw new Error(
    'No Gemini keys found. On n8n Cloud add them under Settings -> Variables as ' +
    'GEMINI_API_KEY_1 ... GEMINI_API_KEY_7 (at least GEMINI_API_KEY_1). ' +
    'Self-hosted instances may use environment variables of the same names. ' +
    'Never paste a key into a node parameter -- it would end up in every export.'
  );
}

const store = $getWorkflowStaticData('global');
store.geminiKeyIndex = (store.geminiKeyIndex ?? 0) % keys.length;

const out = [];
for (const item of $input.all()) {
  const key = keys[store.geminiKeyIndex];
  store.geminiKeyIndex = (store.geminiKeyIndex + 1) % keys.length;
  out.push({
    json: {
      ...item.json,
      geminiKey: key,
      geminiKeyNumber: store.geminiKeyIndex === 0 ? keys.length : store.geminiKeyIndex,
      geminiKeyCount: keys.length,
    },
  });
}
return out;

// Parse Gemini's JSON and refuse anything that would publish badly.
//
// The model is asked for raw JSON, but it still occasionally wraps the object
// in a markdown fence, so strip that before parsing rather than failing the
// whole batch on a formatting quirk.
const out = [];

for (const item of $input.all()) {
  const raw = item.json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  const cleaned = String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();

  let post;
  try {
    post = JSON.parse(cleaned);
  } catch (e) {
    throw new Error('Gemini did not return valid JSON for "' + (item.json.title ?? 'unknown row') + '": ' + e.message);
  }

  const need = ['title', 'slug', 'excerpt', 'content_html', 'image_prompt', 'meta_description'];
  const missing = need.filter((k) => !post[k] || String(post[k]).trim() === '');
  if (missing.length) throw new Error('Post is missing required fields: ' + missing.join(', '));

  // Guards. Each of these has shipped as a real defect on this project before.
  if (/<h1[\s>]/i.test(post.content_html)) throw new Error('content_html contains an <h1>; the theme renders the title.');
  if (/<script|<style|onerror=|onclick=/i.test(post.content_html)) throw new Error('content_html contains script/style/handlers.');
  if (String(post.title).length > 80) throw new Error('Title too long: ' + post.title.length);
  if (String(post.meta_description).length > 165) throw new Error('meta_description too long: ' + post.meta_description.length);

  const words = String(post.content_html).replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;
  if (words < 350) throw new Error('Post is only ' + words + ' words; too thin to publish.');

  post.slug = String(post.slug).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

  out.push({ json: { ...item.json, post, wordCount: words } });
}

return out;
